import { createHash, randomBytes } from "node:crypto";
import { mkdir } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { pathToFileURL } from "node:url";

// Uses only generated bytes. With no --url, starts an isolated loopback server.
const args = new Map(
  process.argv
    .slice(2)
    .filter((arg) => arg !== "--")
    .map((arg) => {
      const [key, ...value] = arg.replace(/^--/, "").split("=");
      return [key, value.join("=")];
    }),
);
if (args.has("help")) {
  console.log(
    "bun run benchmark --mib=256 --receivers=1 [--url=http://localhost:3070] [--output=benchmark-results.json]",
  );
  process.exit(0);
}
function integer(name: string, fallback: number, maximum: number) {
  const value = Number(args.get(name) ?? fallback);
  if (!Number.isSafeInteger(value) || value < 1 || value > maximum) {
    throw new Error(`--${name} must be an integer from 1 to ${maximum}`);
  }
  return value;
}
const mib = integer("mib", 256, 4096);
const receiverCount = integer("receivers", 1, 16);
const size = mib * 1024 * 1024;
const abort = new AbortController();
const deadline = setTimeout(() => abort.abort(new Error("Benchmark exceeded five minutes")), 300_000);
let child: ReturnType<typeof Bun.spawn> | undefined;
let baselineRss = 0;
let peakRss = 0;
let base = args.get("url")?.replace(/\/$/, "");
let channel: any;

async function localServer(): Promise<string> {
  const entry = pathToFileURL(resolve(import.meta.dir, "../src/server.ts")).href;
  // Measure the server process, not the benchmark client's buffers.
  const probe = `await import(${JSON.stringify(entry)}); const sample=()=>console.log("AUDIT_RSS="+process.memoryUsage().rss); sample(); setInterval(sample,100).unref();`;
  const process = Bun.spawn([Bun.which("bun") ?? "bun", "-e", probe], {
    cwd: resolve(import.meta.dir, ".."),
    env: { ...Bun.env, HOST: "127.0.0.1", PORT: "0", PUBLIC_URL: "", DATA_DIR: ":memory:", NODE_ENV: "production" },
    stdout: "pipe",
    stderr: "inherit",
  });
  child = process;
  let resolveReady!: (url: string) => void;
  const ready = new Promise<string>((resolve) => {
    resolveReady = resolve;
  });
  void (async () => {
    let pending = "";
    const decoder = new TextDecoder();
    for await (const chunk of process.stdout) {
      pending += decoder.decode(chunk, { stream: true });
      const lines = pending.split("\n");
      pending = lines.pop()!;
      for (const line of lines) {
        const address = line.match(/AirShare listening on (http:\/\/[^\s]+)/)?.[1];
        if (address) resolveReady(address.replace("localhost", "127.0.0.1"));
        if (line.startsWith("AUDIT_RSS=")) {
          const rss = Number(line.slice("AUDIT_RSS=".length));
          baselineRss ||= rss;
          peakRss = Math.max(peakRss, rss);
        }
      }
    }
  })().catch(() => {});
  let timer: ReturnType<typeof setTimeout>;
  try {
    return await Promise.race([
      ready,
      process.exited.then((code) => {
        throw new Error(`Server exited before startup (${code})`);
      }),
      new Promise<never>((_, reject) => {
        timer = setTimeout(() => reject(new Error("Server startup timed out")), 10_000);
      }),
    ]);
  } finally {
    clearTimeout(timer!);
  }
}

try {
  base ??= await localServer();
  const origin = new URL(base);
  if (!/^https?:$/.test(origin.protocol)) throw new Error("--url must use HTTP or HTTPS");
  const create = await fetch(`${base}/api/channels`, {
    method: "POST",
    signal: abort.signal,
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      filename: "airshare-benchmark.bin",
      contentType: "application/octet-stream",
      contentLength: size,
    }),
  });
  if (!create.ok) throw new Error(`Create channel failed: HTTP ${create.status}`);
  channel = await create.json();

  const downloads = Array.from({ length: receiverCount }, async () => {
    const response = await fetch(channel.downloadUrl, { signal: abort.signal });
    if (!response.ok || !response.body) throw new Error(`Download failed: HTTP ${response.status}`);
    const digest = createHash("sha256");
    let bytes = 0;
    for await (const chunk of response.body) {
      bytes += chunk.byteLength;
      digest.update(chunk);
    }
    return { bytes, sha256: digest.digest("hex") };
  });
  // Attach rejection handlers immediately while the receivers wait for the sender.
  downloads.forEach((task) => {
    void task.catch(() => {});
  });
  const waitUntil = performance.now() + 10_000;
  while (true) {
    const response = await fetch(channel.statusUrl ?? `${base}/api/channels/${channel.id}`, { signal: abort.signal });
    const status = (await response.json()) as { waitingReceivers: number };
    if (status.waitingReceivers === receiverCount) break;
    if (performance.now() > waitUntil) throw new Error("Receivers did not register");
    await Bun.sleep(25);
  }

  const chunk = randomBytes(256 * 1024);
  const sourceHash = createHash("sha256");
  let sent = 0;
  const body = new ReadableStream<Uint8Array>({
    pull(controller) {
      if (sent === size) {
        controller.close();
        return;
      }
      const bytes = chunk.subarray(0, Math.min(chunk.length, size - sent));
      sourceHash.update(bytes);
      sent += bytes.length;
      controller.enqueue(bytes);
    },
  });
  const started = performance.now();
  const upload = await fetch(channel.uploadUrl, {
    method: "PUT",
    body,
    signal: abort.signal,
    headers: {
      "content-type": "application/octet-stream",
      "content-length": String(size),
      "x-airshare-file-size": String(size),
      "x-airshare-no-redirect": "1",
    },
    redirect: "manual",
  });
  if (!upload.ok) throw new Error(`Upload failed: HTTP ${upload.status}: ${(await upload.text()).slice(0, 200)}`);
  await upload.arrayBuffer();
  const results = await Promise.all(downloads);
  const seconds = (performance.now() - started) / 1000;
  const expected = sourceHash.digest("hex");
  if (results.some((result) => result.bytes !== size || result.sha256 !== expected)) {
    throw new Error("Transfer integrity check failed");
  }
  const round = (value: number) => Number(value.toFixed(2));
  const report = {
    checkedAt: new Date().toISOString(),
    origin: origin.origin,
    localLoopback: Boolean(child),
    runtime: Bun.version,
    bytesPerReceiver: size,
    receivers: receiverCount,
    sha256: expected,
    integrity: true,
    elapsedSeconds: round(seconds),
    uploadMiBPerSecond: round(mib / seconds),
    aggregateDownloadMiBPerSecond: round((mib * receiverCount) / seconds),
    serverRssBaselineMiB: child ? round(baselineRss / 1024 / 1024) : undefined,
    serverRssSampledPeakMiB: child ? round(peakRss / 1024 / 1024) : undefined,
    serverRssSampleIntervalMs: child ? 100 : undefined,
    note: "Synthetic transfer plus SHA-256 verification. Loopback throughput is not an Internet or India-to-host speed prediction.",
  };
  if (args.has("output")) {
    const path = resolve(args.get("output")!);
    await mkdir(dirname(path), { recursive: true });
    await Bun.write(path, `${JSON.stringify(report, null, 2)}\n`);
  }
  console.log(JSON.stringify(report, null, 2));
} catch (error) {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
} finally {
  if (channel && base)
    await fetch(channel.deleteUrl ?? `${base}/api/channels/${channel.id}`, {
      method: "DELETE",
      signal: AbortSignal.timeout(2000),
    }).catch(() => {});
  abort.abort();
  clearTimeout(deadline);
  if (child) {
    child.kill();
    await child.exited;
  }
}
